  --brand: saddlebrown;
  --text: #222;
  --space: 16px;
}

body {
  color: var(--text);
}

h1,
nav a {
  color: var(--brand);
}

.sale {
  --brand: crimson;

  & h1::after {
    content: " (sale!)";
  }
}

